\label{def:exp} Given $p,q\in\beta\mathbb{N}$, we let
\begin{eqnarray*}
E_1({p},{q}) &=& \{A\subseteq\mathbb{N}:\{n\in\mathbb{N}:\{m\in\mathbb{N}:n^m\in A\}\in{q}\}\in{p}\};\\
E_2({p},{q}) &=& \{A\subseteq\mathbb{N}:\{n\in\mathbb{N}:\{m\in\mathbb{N}:m^n\in A\}\in{q}\}\in{p}\}.
\end{eqnarray*}

\label{alphthm:A}
Let $p,q\in\beta\mathbb{N}\setminus\{1\}$. 
\begin{enumerate}[label=(\roman*)]
\item If $p$ is highly exponential and ${\rm rad}(q)$ divides ${\rm rad}(p)$, then $q$ divides $p$.
\item Assume that $rad(p)$ does not strictly divide itself and that, for all $q$ such that $rad(q)=rad(p)$, we have that $q$ divides $p$. Then $p$ is highly exponential.
\end{enumerate}

\label{alphthm:B}
Let ${p},{q}\in\beta\mathbb{N}$ be such that $E_1({p},{q})=E_2({q},{p})$. Let $f$ be a factor-picking function with $f(p)\neq 1$ and let $e_{f}$ be its exact exponent. Then 
\begin{enumerate}[label=(\roman*)]
\item $p$ is $f$-highly exponential;
\item $e_{f}({p})\odot{q}={q}\odot e_{f}({p})$.
\end{enumerate}

The following are all factor-picking functions:
\begin{enumerate}
\item for all prime $p$, the function that maps $n$ to $p$ if $p$ divides $n$, or to $1$ otherwise;
\item for all $m\in\mathbb{N}$, the function mapping $n$ to its $m$-th prime divisor, if $n$ has at least $m$ divisors, or to $1$ otherwise;
\item the function mapping $n$ to the product of its first $m$ prime divisors, if $n$ has at least $m$ divisors, or to $1$ otherwise;
\item the function mapping $n$ to the product of its last $m$ prime divisors, if $n$ has at least $m$ divisors, or to $1$ otherwise.
\end{enumerate}

\label{maxhighexp}
For every $p\in\beta\mathbb{N}\setminus\mathbb{N}$, the following conditions are equivalent:

\begin{enumerate}[label=(\roman*)]
\item\label{E1} $p$ is highly exponential;

\item\label{E5} $p$ is $f$-highly exponential for some factor-picking function $f$ such that ${\rm rad}(\alpha)\mid f(\alpha)$ for some $\alpha\models p$;

\item\label{E2} $p$ is ${\rm rad}$-highly exponential;

\item\label{E3} $p$ is $PB$-highly exponential;

\item\label{E4} There exist $\alpha\ll\beta, \alpha>1$ such that $\alpha^{\beta}\models p$.
\end{enumerate}

\label{FundRemCut}
If $\beta=f(\alpha)$ for some $f:\mathbb{N}\rightarrow \mathbb{N}$, then $\alpha^{\beta}\sim \alpha^{\beta^{\prime}}$ if and only if $\beta=\beta^{\prime}$.

If $\beta\neq f(\alpha)$ for all $f:\mathbb{N}\rightarrow\mathbb{N}$, let $F_{\beta}=\{f:\mathbb{N}\rightarrow \mathbb{N}\mid f(\alpha)<\beta\}$ and let $I_{\beta}=\{\gamma\in\,^{\ast}\mathbb{N}\mid \forall f\in F_{\beta}\ \forall g\in F_{\beta}^{c}\ f(\alpha)<\gamma<g(\alpha)\}$. Then:
\begin{enumerate}[label=(\roman*)]
\item $\alpha^{\beta}\sim \alpha^{\beta^{\prime}}\Rightarrow F_{\beta}=F_{\beta^{\prime}}$;
\item the set $\{\beta^{\prime}\in\,^{\ast}\mathbb{N}\mid \alpha^{\beta}\sim \alpha^{\beta^{\prime}}\}$ is coinitial and cofinal in $I_{\beta}$.
\end{enumerate}

Let $p,q\in\beta\mathbb{N}$. We say that:
\begin{enumerate}
\item[(a)] $p$ divides $q$ if there exist $\alpha\in\mu(p),\beta\in\mu(q)$ such that $\alpha|\beta$;
\item[(b)] $p$ strictly divides itself if there exist distinct $\alpha,\beta\in\mu(p)$ such that $\alpha|\beta$.
\end{enumerate}

\label{FundProb}
Characterize nonprincipal ultrafilters $p,q$ for which 
\begin{equation}\label{FundEq} E_1({p},{q})=E_2({q},{p}). \end{equation} 
Equivalently, characterize tensor pairs $(\alpha_{1},\beta_{1}),(\beta_{2},\alpha_{2})$ in $^{\ast}\mathbb{N}^{2}$ for which $\alpha_{1}\sim\alpha_{2},\beta_{1}\sim\beta_{2},\alpha_{1}^{\beta_{1}}\sim\alpha_{2}^{\beta_{2}}$.

Assume that $E_1({p},{q})=E_2({q},{p})$. By Theorem \ref{alphthm:B}, $p$ is $f$-highly exponential for all factor-picking $f$. Let $\alpha=\prod_{i=1}^{\nu}p_{l(i)}^{k_{i}}$ be a generator of $p$, where $p_{l(i)}$ is the $l(i)$-th prime in $^{\ast}\mathbb{N}$ (hence $k_{i}>0$ for all $i\leq \nu$). In particular:
\begin{enumerate}
\item $PB(\alpha)\ll PE(\alpha)$, hence by Lemma \ref{highexp} $p_{l(i)}\ll k_{i}$ for all $i\leq \nu$;
\item if $\nu=m\in\mathbb{N}$, by taking for $j\leq m$ the factor-picking $f_{j}$ that maps $n$ to its $j$-th prime divisor, we deduce that $e_{f_{j}}(p)\odot q=q\odot e_{f_{j}}(p)$, namely $q$ commutes with all the ultrafilters generated by exponents of prime factorization of a generator of $p$.
\end{enumerate}

Let us show that $(1), (2)$ from Theorem \ref{alphthm:B} are independent.

\begin{enumerate}
\item It is known (see \cite[Theorem 6.10]{HS}) that the center of $(\beta\mathbb{N},\odot)$ is $\mathbb{N}$. Pick $q$ nonprincipal, let $u$ be such that $u\odot q\neq q\odot u$ and let $p=2^{u}$. Then $p$ is $f$-highly exponential for all factor-picking $f$ with $f(2)\neq 1$, as in this case necessarily $f(2)=2$, whilst $e_{f}(p)=u$. Hence $e_{f}(p)\odot q=u\odot q\neq q\odot u=q\odot e_{f}(p)$ (and, in fact, $E_{1}(p,q)=2^{u\odot q}\neq 2^{q\odot u}= E_{2}(q,p)$).
\item Now let $p$ be generated by an infinite prime $\alpha$. Trivially, $e_{f}(\alpha)=1$ for all $f$ factor-picking, hence $e_{f}(p)\odot q=q\odot e_{f}(p)$ for all $q\in\beta\mathbb{N}$. But $p$ is not $f$-highly exponential, hence $E_{1}(p,q)\neq E_{2}(q,p)$ for all $q\in\beta\mathbb{N}\setminus\mathbb{N}$.
\end{enumerate}

\label{ReformulationRm} By Lemma \ref{lem:list}.\ref{T2}, $\alpha_{1}^{\beta_{1}}\sim\alpha_{2}^{\beta_{2}}$ if and only if there exists $(\alpha_{3},\beta_{3})\sim (\alpha_{2},\beta_{2})$ such that $\alpha_{1}^{\beta_{1}}=\alpha_{3}^{\beta_{3}}$, which is easily settled: there must be some $\gamma\in\,^{\ast}\mathbb{Q}$ such that either
\begin{enumerate}
\item $\alpha_{3}=\alpha_{1}^{\gamma}, \beta_{1}=\beta_{3}\gamma$, or
\item $\alpha_{1}=\alpha_{3}^{\gamma}, \beta_{3}=\beta_{1}\gamma$.
\end{enumerate}
